  case 6: /* (4,2) */ *c0 = -0.0035430839002267574*pow(q, 7) + 0.0099206349206349206*pow(q, 5) - 0.0048028470647518267*pow(q, 3) - 0.0028344671201814059*q; return 8;
  case 7: /* (4,3) */ *c0 = 0.09765625*pow(q, 7) - 0.13288225446428571*pow(q, 5) - 0.19670758928571429*pow(q, 3) - 0.022321428571428571*q; return 10;
  case 8: /* (4,4) */ *c0 = -0.69444444444444444*pow(q, 7) - 1.1706349206349206*pow(q, 5) - 0.37257495590828924*pow(q, 3) - 0.019841269841269841*q; return 8;
  case 9: /* (5,1) */ *c0 = -6.7640692640692641e-5*pow(q, 9) + 0.00030889249639249639*pow(q, 7) - 0.00052719813462000962*pow(q, 5) + 0.00039867298981882315*pow(q, 3) - 0.00011273448773448773*q; return 12;
  case 10: /* (5,2) */ *c0 = 0.0021212121212121212*pow(q, 9) - 0.0084646464646464646*pow(q, 7) + 0.0099461279461279461*pow(q, 5) - 0.0017261503928170595*pow(q, 3) - 0.0020202020202020202*q; return 14;
  case 11: /* (5,3) */ *c0 = -0.0033143939393939394*pow(q, 9) + 0.0096886837121212121*pow(q, 7) - 0.00037064985795454545*pow(q, 5) - 0.0096738873106060606*pow(q, 3) - 0.0011837121212121212*q; return 12;
  case 12: /* (5,4) */ *c0 = 0.076363636363636364*pow(q, 9) - 0.083393939393939394*pow(q, 7) - 0.31660606060606061*pow(q, 5) - 0.11162289562289562*pow(q, 3) - 0.0060606060606060606*q; return 14;
  case 13: /* (5,5) */ *c0 = -0.74573863636363636*pow(q, 9) - 1.9183534564393939*pow(q, 7) - 1.1568011659564394*pow(q, 5) - 0.18696897359006734*pow(q, 3) - 0.0059185606060606061*q; return 12;
  case 14: /* (6,1) */ *c0 = 0.; return 0;
  case 15: /* (6,2) */ *c0 = -8.2409173318264227e-5*pow(q, 11) + 0.00042156216398640641*pow(q, 9) - 0.00075636578161830687*pow(q, 7) + 0.00050176939907579638*pow(q, 5) + 3.0412909200787989e-6*pow(q, 3) - 8.8295542840997386e-5*q; return 16;
  case 16: /* (6,3) */ *c0 = 0.; return 0;
  case 17: /* (6,4) */ *c0 = -0.0029667302394575122*pow(q, 11) + 0.0085799722163358527*pow(q, 9) + 0.0064684137411410139*pow(q, 7) - 0.01780373012696245*pow(q, 5) - 0.0075703421157966613*pow(q, 3) - 0.00042381860563678746*q; return 16;
  case 18: /* (6,5) */ *c0 = 0.; return 0;
  case 19: /* (6,6) */ *c0 = -0.80769230769230769*pow(q, 11) - 2.8750874125874126*pow(q, 9) - 2.7211713286713287*pow(q, 7) - 0.85190559440559441*pow(q, 5) - 0.083374125874125874*pow(q, 3) - 0.0017482517482517483*q; return 16;
